-- Minimal disposable PostgreSQL schema for the calendar-schedule RPC tests.
DO $$ BEGIN CREATE ROLE anon; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE supabase_admin; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE tournaments (id uuid PRIMARY KEY, season integer DEFAULT 1, league_category text, status text DEFAULT 'open', schedule_mode text, schedule_start_slot timestamptz, schedule_locked_at timestamptz, registration_closed_at timestamptz, schedule_generated_at timestamptz, include_week15_weekend_friendly boolean);
CREATE TABLE teams (id uuid PRIMARY KEY, tournament_id uuid, name text, ht_team_id bigint, hattrick_user_id bigint, active boolean DEFAULT true, reserve_active boolean DEFAULT false, is_placeholder boolean DEFAULT false, team_rank integer, power_rating integer, manager_name text, logo_url text);
CREATE TABLE tournament_seasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tournament_id uuid, season_number integer, status text, planned_start_slot timestamptz, started_at timestamptz, finished_at timestamptz, updated_at timestamptz, schedule_plan_json jsonb, ranking_snapshot_json jsonb, champion_team_id uuid, champion_slot_id uuid, champion_decided_at timestamptz, UNIQUE(tournament_id,season_number));
CREATE TABLE tournament_season_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tournament_season_id uuid, slot_index integer, box_size integer, current_team_id uuid);
CREATE TABLE tournament_season_slot_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tournament_season_slot_id uuid, team_id uuid, reason text, team_name text, ht_team_id bigint, manager_name text, hattrick_user_id bigint, logo_url text, released_at timestamptz);
CREATE TABLE rounds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tournament_id uuid, season_number integer, round_number integer, phase text, phase_round_number integer, phase_status text, reserved_slot_id text, reserved_slot_kind text, reserved_slot_date timestamptz, reserved_display_date timestamptz, materialized_at timestamptz, completed_at timestamptz);
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), round_id uuid, home_team_id uuid, away_team_id uuid, home_slot_id uuid, away_slot_id uuid, home_slot_assignment_id uuid, away_slot_assignment_id uuid, venue_type text, scheduled_for timestamptz, schedule_slot_type text, completed boolean DEFAULT false, total_minutes integer, schedule_resolution text DEFAULT 'pending', status text DEFAULT 'not_arranged', ht_match_id bigint);
